<script setup>
import CustomerLayout from '@/Layouts/CustomerLayout.vue';
import ProductCard from '@/Components/ProductCard.vue';
import { Link, usePage } from '@inertiajs/vue3';
import { computed, ref } from 'vue';

defineProps({ categories: Array, featuredProducts: Array, bestSellingProducts: Array, allProducts: Array, branches: Array, selectedBranch: Object, activeCoupons: Array });
const page = usePage();
const settings = computed(() => page.props.settings || {});
const selectedBranch = computed(() => page.props.selectedBranch || null);
const featuredProducts = computed(() => page.props.featuredProducts || []);
const bestSellingProducts = computed(() => page.props.bestSellingProducts || featuredProducts.value);
const allProducts = computed(() => page.props.allProducts || []);
const categories = computed(() => page.props.categories || []);
const branches = computed(() => page.props.branches || []);
const activeCoupons = computed(() => page.props.activeCoupons || []);
const tickerCoupons = computed(() => [...activeCoupons.value, ...activeCoupons.value]);
const categoryMenuOpen = ref(false);
const categoryTrack = ref(null);
const toast = ref({ show: false, product: null });
let toastTimer;

const assetUrl = path => path?.startsWith('http') ? path : '/storage/' + path;
const branchDisplayName = branch => branch?.name_bn ? `${branch.name} · ${branch.name_bn}` : branch?.name || '';
const money = value => Number(value || 0).toLocaleString('en-BD', { maximumFractionDigits: 0 });
const couponOffer = coupon => coupon.type === 'percentage' ? `${coupon.value}% off` : `৳${money(coupon.value)} off`;
const categoryMark = name => ({ Cake: 'CK', Bread: 'BR', Cookies: 'CO', Sweets: 'SW', 'Fast Food': 'FF', Toast: 'TO', Dessert: 'DS', 'Order Cake': 'OC' }[name] || 'LV');
const productEmoji = product => ({ Cake: '🎂', Bread: '🍞', Cookies: '🍪', Sweets: '🍬', 'Fast Food': '🍔', Dessert: '🍮' }[product?.category?.name] || '🍰');
const fallbackHeroImages = ['/images/lakeview-hero.jpg', '/images/lakeview-sweets.jpg', '/images/lakeview-cake.jpg'];
const heroImages = computed(() => { try { const configured = JSON.parse(settings.value.hero_images || '[]').filter(Boolean); return configured.length ? configured : fallbackHeroImages; } catch { return fallbackHeroImages; } });
const heroImage = index => heroImages.value[index % heroImages.value.length] || '';
const addToCart = (product, amount = 1) => { let cart = []; try { cart = JSON.parse(localStorage.getItem('cart') || '[]'); } catch { cart = []; } const existing = cart.find(item => item.product_id === product.id); if (existing) { existing.quantity += amount; existing.image = product.image || existing.image; existing.category_name = product.category?.name || existing.category_name || ''; existing.allow_pickup = product.allow_pickup !== false; existing.allow_home_delivery = product.allow_home_delivery !== false; } else cart.push({ product_id: product.id, name: product.name, category_name: product.category?.name || '', image: product.image || '', price: Number(product.effective_price), quantity: amount, allow_pickup: product.allow_pickup !== false, allow_home_delivery: product.allow_home_delivery !== false }); localStorage.setItem('cart', JSON.stringify(cart)); window.dispatchEvent(new Event('cart-updated')); toast.value = { show: true, product }; clearTimeout(toastTimer); toastTimer = window.setTimeout(() => { toast.value.show = false; }, 3200); };
</script>
